 // --- Render Bookings Table ---
 function renderBookings(period, bookings) {
 console.log(`Rendering bookings for period: ${period}`);
 const tbody = document.getElementById(`${period}BookingsTableBody`);
 if (!tbody) {
 console.warn(`Table body element not found for period: ${period}`);
 return;
 }
 tbody.innerHTML = '';

 if (bookings.length === 0) {
 tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;padding:40px;color:#666;">No bookings for ${period.replace(/([A-Z])/g, ' $1').toLowerCase()}</td></tr>`;
 } else {
 bookings.forEach(b => {
 const row = tbody.insertRow();

 // Safely format date (YYYY-MM-DD)
 const dateDisplay = b.booking_date ? new Date(b.booking_date).toLocaleDateString('en-CA', { timeZone: SAST_TIMEZONE }) : '-';

 // Safely format time (HH:MM)
 const timeDisplay = b.booking_time ? new Date(`1970-01-01T${b.booking_time.split(':')[0]}:${b.booking_time.split(':')[1]}:00`).toLocaleTimeString('en-ZA', { timeZone: SAST_TIMEZONE, hour: '2-digit', minute: '2-digit', hour12: false }) : '-';

 // Patient type and class for styling
 let patientTypeDisplay = b.patient_type || 'Private';
 let patientTypeClass = 'private';
 if (b.patient_type === 'Medical Aid') {
 patientTypeClass = 'medical-aid';
 }

 // Safely format price for display. Use 0 if missing or invalid.
 const priceDisplay = `R${Number(b.service_price || 0).toFixed(2)}`;

 row.innerHTML = `
 <td>${dateDisplay}</td>
 <td>${timeDisplay}</td>
 <td>${b.client_name || 'N/A'}<br><small>${b.client_email || ''}</small></td>
 <td>${b.client_phone || '-'}</td>
 <td>${b.service_name || '-'}</td>
 <td>${priceDisplay}</td>
 <td><span class="patient-type ${patientTypeClass}">${patientTypeDisplay}</span></td>
 `;
 });
 }
 }

 function showDashboard() {
 console.log("showDashboard function called.");
 const businessId = localStorage.getItem('businessId');
 if (!businessId) {
 console.log("No businessId found in localStorage. Showing login card.");
 const loginCard = document.getElementById('loginCard');
 if (loginCard) loginCard.style.display = 'block';
 const dashboard = document.getElementById('dashboard');
 if (dashboard) dashboard.style.display = 'none';
 return;
 }

 console.log("Business ID found:", businessId);
 const loginCard = document.getElementById('loginCard');
 const dashboard = document.getElementById('dashboard');

 if (loginCard) {
 loginCard.style.display = 'none';
 console.log("Login card hidden.");
 }
 if (!dashboard) {
 console.error("Dashboard element not found!");
 return;
 }
 dashboard.style.display = 'block';
 console.log("Dashboard displayed.");

 fetch(`/api/bookings/${businessId}`)
 .then(res => {
 if (!res.ok) {
 console.error(`API response not OK. Status: ${res.status}, StatusText: ${res.statusText}`);
 return res.text().then(text => {
 console.error("Raw API response text:", text);
 throw new Error(`HTTP error! status: ${res.status}. Could not fetch bookings. ${text}`);
 });
 }
 return res.json();
 })
 .then(data => {
 console.log("Dashboard data received:", data);
 const boundaries = getDateBoundariesSAST();

 // --- Helper functions for formatting ---
 const formatCurrency = (value) => {
 const num = Number(value || 0);
 return `R${num.toFixed(2)}`;
 };
 const formatCount = (value) => value || '0';

 // Update counts and revenue - use safe access and formatting
 document.getElementById('todayCount').textContent = formatCount(data.overview?.totalAppointmentsToday);
 document.getElementById('weekCount').textContent = formatCount(data.overview?.totalAppointmentsThisWeek);
 document.getElementById('nextWeekCount').textContent = formatCount(data.overview?.totalAppointmentsNextWeek);
 document.getElementById('revenueLastWeek').textContent = formatCurrency(data.revenue?.totalRevenueLastWeek);
 document.getElementById('revenueThisWeek').textContent = formatCurrency(data.revenue?.totalRevenueThisWeek);
 document.getElementById('revenueThisMonth').textContent = formatCurrency(data.revenue?.totalRevenueThisMonth);

 // Filter and Render Bookings
 let todayBookings = [];
 let tomorrowBookings = [];
 let thisWeekBookings = [];
 let nextWeekBookings = [];
 let thisMonthBookings = [];
 let nextMonthBookings = [];
 let longTermBookings = [];

 const bookings = data.bookings || []; 

 if (bookings.length > 0) {
 bookings.forEach(b => {
 if (!b.booking_date) {
 console.warn("Booking found with no booking_date:", b);
 return;
 }
 try {
 const bookingDateTimeUTC = new Date(`${b.booking_date}T${b.booking_time || '00:00:00'}`);
 if (isNaN(bookingDateTimeUTC.getTime())) {
 console.warn("Invalid date/time parsed for booking:", b);
 return;
 }

 const bookingDateUTC = new Date(bookingDateTimeUTC);
 bookingDateUTC.setUTCHours(0,0,0,0); 

 // --- Revenue Calculation Logic ---
 const isCompleted = b.status === 'completed';
 const isPastOrPresent = bookingDateUTC.getTime() <= boundaries.startOfToday.getTime();

 const price = Number(b.service_price || 0);
 const displayPrice = (isCompleted && isPastOrPresent) ? price : 0;

 // --- Assign to date ranges ---
 // Today
 if (bookingDateUTC.getTime() >= boundaries.startOfToday.getTime() && bookingDateUTC.getTime() < boundaries.startOfTomorrow.getTime()) {
 todayBookings.push({...b, service_price: displayPrice, service_name: b.service_name || b.service_id || '-'});
 } 
 // Tomorrow (exactly one day ahead)
 const isExactlyTomorrow = bookingDateUTC.getTime() >= boundaries.startOfTomorrow.getTime() && bookingDateUTC.getTime() < (boundaries.startOfTomorrow.getTime() + 24 * 60 * 60 * 1000);
 if (isExactlyTomorrow) {
 tomorrowBookings.push({...b, service_price: displayPrice, service_name: b.service_name || b.service_id || '-'});
 }

 // This Week (Monday to Saturday UTC)
 if (bookingDateUTC.getTime() >= boundaries.startOfThisWeek.getTime() && bookingDateUTC.getTime() < boundaries.startOfNextWeek.getTime()) {
 thisWeekBookings.push({...b, service_price: displayPrice, service_name: b.service_name || b.service_id || '-'});
 } 
 // Next Week (Monday to Saturday UTC)
 if (bookingDateUTC.getTime() >= boundaries.startOfNextWeek.getTime() && bookingDateUTC.getTime() <= boundaries.endOfNextWeek.getTime()) {
 nextWeekBookings.push({...b, service_price: displayPrice, service_name: b.service_name || b.service_id || '-'});
 }

 // This Month (UTC)
 if (bookingDateUTC.getTime() >= boundaries.startOfThisMonth.getTime() && bookingDateUTC.getTime() <= boundaries.endOfThisMonth.getTime()) {
 thisMonthBookings.push({...b, service_price: displayPrice, service_name: b.service_name || b.service_id || '-'});
 }
 // Next Month (UTC)
 if (bookingDateUTC.getTime() >= boundaries.startOfNextMonth.getTime() && bookingDateUTC.getTime() <= boundaries.endOfNextMonth.getTime()) {
 nextMonthBookings.push({...b, service_price: displayPrice, service_name: b.service_name || b.service_id || '-'});
 }
 // Long-Term (anything older than last month or newer than next month)
 else if (bookingDateUTC.getTime() < boundaries.startOfLastMonth.getTime() || bookingDateUTC.getTime() > boundaries.endOfNextMonth.getTime()) {
 longTermBookings.push({...b, service_price: displayPrice, service_name: b.service_name || b.service_id || '-'});
 }

 } catch (dateError) {
 console.error("Error processing date for booking:", b, dateError);
 }
 });
 } else {
 console.log("No bookings array or bookings array is empty.");
 }

 // Render tables
 renderBookings('today', todayBookings);
 renderBookings('tomorrow', tomorrowBookings);
 renderBookings('thisWeek', thisWeekBookings);
 renderBookings('nextWeek', nextWeekBookings);
 renderBookings('thisMonth', thisMonthBookings);
 renderBookings('nextMonth', nextMonthBookings);
 renderBookings('longTerm', longTermBookings);

 // Auto-open the main bookings section if there are any bookings
 const bookingsByDateContent = document.getElementById('bookingsByDateContent');
 const bookingsByDateIcon = document.getElementById('bookingsByDateIcon');
 if (bookingsByDateContent && bookingsByDateIcon && (todayBookings.length + tomorrowBookings.length + thisWeekBookings.length + nextWeekBookings.length + thisMonthBookings.length + nextMonthBookings.length + longTermBookings.length > 0)) {
 if (!bookingsByDateContent.classList.contains('open')) {
 bookingsByDateContent.classList.add('open');
 bookingsByDateIcon.classList.add('open');
 console.log("Bookings section opened due to available bookings.");
 }
 } else {
 console.log("Bookings section not opened (no bookings or elements missing).");
 }

 // Close OTHER collapse sections if they were open, except the main bookings section
 document.querySelectorAll('.collapsible-sub-section > .collapsible-content').forEach(content => {
 if (!content.id.includes('bookingsByDateContent') && content.classList.contains('open')) {
 content.classList.remove('open');
 const icon = document.getElementById(content.id.replace('Content', 'Icon'));
 if (icon) icon.classList.remove('open');
 console.log(`Closed other collapsible section: ${content.id}`);
 }
 });
 })
 .catch(err => {
 console.error('Error loading dashboard data:', err);
 const errMessageEl = document.createElement('p');
 errMessageEl.textContent = `Failed to load dashboard data. Please check console for details or contact support.`;
 errMessageEl.style.color = 'red';
 errMessageEl.style.textAlign = 'center';
 errMessageEl.style.padding = '20px';
 errMessageEl.style.fontSize = '1.1em';
 const dashboard = document.getElementById('dashboard');
 if (dashboard) {
 dashboard.innerHTML = '';
 dashboard.appendChild(errMessageEl);
 } else {
 console.error("Dashboard element not found to display error message.");
 }
 });
 }

 // --- DOMContentLoaded ---
 document.addEventListener('DOMContentLoaded', () => {
 console.log("DOM fully loaded. Initializing admin page...");
 const loginCard = document.getElementById('loginCard');
 const dashboard = document.getElementById('dashboard');

 if (!loginCard || !dashboard) {
 console.error("Required DOM elements (loginCard, dashboard) not found!");
 return;
 }

 if (localStorage.getItem('businessId')) {
 console.log("Business ID found in localStorage. Attempting to show dashboard.");
 loginCard.style.display = 'none';
 dashboard.style.display = 'block';
 showDashboard();
 } else {
 console.log("No business ID found. Displaying login card.");
 loginCard.style.display = 'block';
 dashboard.style.display = 'none';
 }
 });
 </script>
</body>
</html>
