 const API_BASE = ''; // Relative paths for API calls
 const SAST_TIMEZONE = 'Africa/Johannesburg';

 // --- Date Boundary Calculation ---
 function getDateBoundariesSAST(date = new Date()) {
 const year = date.getFullYear();
 const month = date.getMonth();

 const startOfDayUTC = (y, m, d) => new Date(Date.UTC(y, m, d));

 const nowSAST = new Date(date.toLocaleString('en-ZA', { timeZone: SAST_TIMEZONE }));
 const currentDaySAST = nowSAST.getDate();
 const currentMonthSAST = nowSAST.getMonth();
 const currentYearSAST = nowSAST.getFullYear();
 const currentDayOfWeekJS = nowSAST.getDay(); // Sunday = 0, Monday = 1, ..., Saturday = 6

 const startOfToday = startOfDayUTC(currentYearSAST, currentMonthSAST, currentDaySAST);

 const startOfTomorrow = new Date(startOfToday);
 startOfTomorrow.setUTCDate(startOfToday.getUTCDate() + 1);

 const diffToMonday = currentDayOfWeekJS === 0 ? 6 : currentDayOfWeekJS - 1;
 const startOfThisWeekUTC = startOfDayUTC(currentYearSAST, currentMonthSAST, currentDaySAST - diffToMonday);

 const startOfNextWeekUTC = new Date(startOfThisWeekUTC);
 startOfNextWeekUTC.setUTCDate(startOfThisWeekUTC.getUTCDate() + 7);

 const endOfNextWeekSaturdayUTC = new Date(startOfNextWeekUTC);
 endOfNextWeekSaturdayUTC.setUTCDate(startOfNextWeekUTC.getUTCDate() + 5);
 endOfNextWeekSaturdayUTC.setUTCHours(23, 59, 59, 999);

 const startOfThisMonthUTC = startOfDayUTC(currentYearSAST, currentMonthSAST, 1);
 const endOfThisMonthUTC = new Date(Date.UTC(currentYearSAST, currentMonthSAST + 1, 0));
 endOfThisMonthUTC.setUTCHours(23, 59, 59, 999);

 const startOfNextMonthUTC = new Date(Date.UTC(currentYearSAST, currentMonthSAST + 1, 1));
 const endOfNextMonthUTC = new Date(Date.UTC(currentYearSAST, currentMonthSAST + 2, 0));
 endOfNextMonthUTC.setUTCHours(23, 59, 59, 999);

 const startOfLastMonthUTC = new Date(Date.UTC(currentYearSAST, currentMonthSAST - 1, 1));
 const endOfLastMonthUTC = new Date(Date.UTC(currentYearSAST, currentMonthSAST, 0));
 endOfLastMonthUTC.setUTCHours(23, 59, 59, 999);

 return {
 startOfToday: startOfToday,
 startOfTomorrow: startOfTomorrow,
 startOfThisWeek: startOfThisWeekUTC,
 startOfNextWeek: startOfNextWeekUTC,
 endOfNextWeek: endOfNextWeekSaturdayUTC,
 startOfThisMonth: startOfThisMonthUTC,
 endOfThisMonth: endOfThisMonthUTC,
 startOfNextMonth: startOfNextMonthUTC,
 endOfNextMonth: endOfNextMonthUTC,
 startOfLastMonth: startOfLastMonthUTC,
 endOfLastMonth: endOfLastMonthUTC
 };
